import SwiftUI
struct ProfileView:View{
 @Environment(AppStore.self)private var store;@AppStorage("cook.notifications")private var notifications=true;@AppStorage("cook.metric")private var metric=true
 var body:some View{List{Section{HStack(spacing:16){Image(systemName:"person.crop.circle.fill").font(.system(size:58)).foregroundStyle(CookTheme.green);VStack(alignment:.leading){Text("My Cook").font(.title2.bold());Text("\(store.recipes.count) saved recipes").foregroundStyle(.secondary)}}.padding(.vertical,8)};Section("Preferences"){Toggle("Notifications",isOn:$notifications);Toggle("Metric units",isOn:$metric)};Section("Data"){LabeledContent("Recipes",value:"\(store.recipes.count)");LabeledContent("Groceries",value:"\(store.groceries.count)")};Section{NavigationLink("Privacy & Data"){Text("Your recipes are stored locally in this build. Server sync will use the project privacy and RLS rules.").padding()};NavigationLink("About Cook"){Text("Cook turns recipes you find into a personal cookbook.").padding()}}}.navigationTitle("Me")}
}
